import"./chunk-VC46IEJQ.js";var e={group:"stormlands",places:[{id:"storms-end",summary:{en:"Ancestral seat of the Storm Kings and then of House Baratheon, raised on the cliffs above Shipbreaker Bay. Legend says Durran Godsgrief built six castles that the gods' storms threw down before the seventh, with Bran the Builder's help, finally stood. Its curved walls and single great drum tower have never been taken by storm, and Stannis held it through a year-long siege during Robert's Rebellion.",zh:"\u98CE\u66B4\u4E4B\u738B\u7684\u7956\u5C45\uFF0C\u540E\u4E3A\u62DC\u62C9\u5E2D\u6069\u5BB6\u65CF\u5C45\u57CE\uFF0C\u77D7\u7ACB\u4E8E\u7834\u8239\u6E7E\u7554\u7684\u60AC\u5D16\u4E4B\u4E0A\u3002\u4F20\u8BF4\u201C\u795E\u6012\u201D\u675C\u5170\u8FDE\u5EFA\u516D\u5EA7\u57CE\u5821\u7686\u88AB\u4F17\u795E\u7684\u98CE\u66B4\u6467\u6BC1\uFF0C\u7B2C\u4E03\u5EA7\u5728\u7B51\u57CE\u8005\u5E03\u5170\u767B\u534F\u52A9\u4E0B\u7EC8\u4E8E\u5C79\u7ACB\u4E0D\u5012\u3002\u5176\u5F27\u5F62\u57CE\u5899\u4E0E\u552F\u4E00\u4E00\u5EA7\u5DE8\u5927\u7684\u5706\u5F62\u5854\u697C\u4ECE\u672A\u88AB\u5F3A\u653B\u653B\u7834\uFF1B\u52B3\u52C3\u53DB\u4E71\u671F\u95F4\uFF0C\u53F2\u5766\u5C3C\u65AF\u66FE\u5728\u6B64\u575A\u5B88\u957F\u8FBE\u4E00\u5E74\u7684\u56F4\u57CE\u3002"},houses:["baratheon","durrandon","penrose"],refs:["agot","acok","asos","twoiaf"],confidence:"high",spoiler:{en:"In 299 AC Renly besieges the castle and dies in his camp before its walls; its castellan Ser Cortnay Penrose dies soon after, and the castle passes to Stannis. Davos later smuggles Robert's bastard Edric Storm away from Dragonstone.",zh:"299\u5E74\uFF0C\u84DD\u793C\u5175\u56F4\u6B64\u57CE\uFF0C\u5374\u6B7B\u5728\u57CE\u4E0B\u7684\u8425\u5E10\u4E4B\u4E2D\uFF1B\u4EE3\u7406\u57CE\u4E3B\u79D1\u5854\u5948\xB7\u76D8\u7F57\u65AF\u7235\u58EB\u968F\u5373\u8EAB\u4EA1\uFF0C\u57CE\u5821\u843D\u5165\u53F2\u5766\u5C3C\u65AF\u4E4B\u624B\u3002\u540E\u6765\u6234\u4F5B\u65AF\u5C06\u52B3\u52C3\u7684\u79C1\u751F\u5B50\u827E\u5FB7\u745E\u514B\xB7\u98CE\u66B4\u5077\u5077\u9001\u79BB\u9F99\u77F3\u5C9B\u3002"}},{id:"kingswood",kind:"forest",region:"stormlands",at:[494,976],rank:4,names:{en:"The Kingswood",zh:"\u5FA1\u6797"},alt:["Kingswood","\u56FD\u738B\u68EE\u6797"],summary:{en:"A great old forest of oak and undergrowth spreading south of King's Landing towards Storm's End, crossed by the kingsroad. In Aerys II's reign it sheltered the outlaw Kingswood Brotherhood until Ser Arthur Dayne and other knights of the Kingsguard broke them; the young Jaime Lannister was knighted during that campaign.",zh:"\u4E00\u7247\u53E4\u8001\u8FBD\u9614\u7684\u6A61\u6811\u6797\uFF0C\u4ECE\u541B\u4E34\u4EE5\u5357\u4E00\u76F4\u5EF6\u4F38\u5230\u98CE\u606F\u5821\u65B9\u5411\uFF0C\u56FD\u738B\u5927\u9053\u7A7F\u6797\u800C\u8FC7\u3002\u4F0A\u91CC\u65AF\u4E8C\u4E16\u5728\u4F4D\u65F6\uFF0C\u201C\u5FA1\u6797\u5144\u5F1F\u4F1A\u201D\u76D7\u532A\u85CF\u8EAB\u6797\u4E2D\uFF0C\u76F4\u5230\u4E9A\u745F\xB7\u6234\u6069\u7235\u58EB\u7B49\u5FA1\u6797\u94C1\u536B\u5C06\u5176\u527F\u706D\uFF1B\u5E74\u5C11\u7684\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279\u4FBF\u662F\u5728\u90A3\u6B21\u5F81\u8BA8\u4E2D\u53D7\u5C01\u9A91\u58EB\u3002"},houses:[],refs:["agot","asos","twoiaf"],confidence:"high"},{id:"wendwater",kind:"river",region:"stormlands",at:[506,1012],rank:2,names:{en:"The Wendwater",zh:"\u6E29\u5FB7\u6CB3"},alt:["Wendwater"],summary:{en:"A river of the northern stormlands that runs east along the southern edge of the Kingswood to Shipbreaker Bay, north of Storm's End. It is a feature of the official maps more than of the novels' action, and its course here is approximate.",zh:"\u98CE\u66B4\u5730\u5317\u90E8\u7684\u4E00\u6761\u6CB3\u6D41\uFF0C\u6CBF\u5FA1\u6797\u5357\u7F18\u5411\u4E1C\u6D41\u5165\u7834\u8239\u6E7E\uFF0C\u6CB3\u53E3\u4F4D\u4E8E\u98CE\u606F\u5821\u4EE5\u5317\u3002\u5B83\u4E3B\u8981\u89C1\u4E8E\u5B98\u65B9\u5730\u56FE\uFF0C\u5728\u5C0F\u8BF4\u60C5\u8282\u4E2D\u7740\u58A8\u4E0D\u591A\uFF1B\u6B64\u5904\u6240\u7ED8\u6CB3\u9053\u4EC5\u4E3A\u5927\u81F4\u8D70\u5411\u3002"},houses:[],refs:["maps","twoiaf"],confidence:"medium"},{id:"slayne",kind:"river",region:"stormlands",at:[490,1132],rank:1,names:{en:"The Slayne",zh:"\u65AF\u96F7\u6069\u6CB3"},alt:["Slayne"],summary:{en:"A river of the southern stormlands that drains the Dornish Marches towards the Sea of Dorne, near Stonehelm and the northern end of the Boneway. Known from the official maps; its exact course is not described in the novels.",zh:"\u98CE\u66B4\u5730\u5357\u90E8\u7684\u4E00\u6761\u6CB3\u6D41\uFF0C\u4ECE\u591A\u6069\u8FB9\u7586\u5730\u5411\u591A\u6069\u6D77\u6D41\u53BB\uFF0C\u9760\u8FD1\u77F3\u76D4\u57CE\u4E0E\u9AB8\u9AA8\u8DEF\u5317\u7AEF\u3002\u6B64\u6CB3\u89C1\u4E8E\u5B98\u65B9\u5730\u56FE\uFF0C\u5C0F\u8BF4\u4E2D\u5E76\u672A\u63CF\u8FF0\u5176\u786E\u5207\u6D41\u5411\u3002"},houses:[],refs:["maps","twoiaf"],confidence:"low"},{id:"rainwood",kind:"forest",region:"stormlands",at:[594,1076],rank:3,names:{en:"The Rainwood",zh:"\u96E8\u6797"},alt:["Rainwood"],summary:{en:"A dense, dripping forest that covers much of Cape Wrath, fed by the storms that blow in off the Narrow Sea. Its tangled, boggy country made it a hard place to hunt down outlaws or move an army through.",zh:"\u8986\u76D6\u6012\u89D2\u5927\u90E8\u7684\u4E00\u7247\u8302\u5BC6\u6E7F\u6797\uFF0C\u72ED\u6D77\u5439\u6765\u7684\u98CE\u66B4\u4F7F\u5B83\u7EC8\u5E74\u6EF4\u6C34\u4E0D\u6B62\u3002\u6797\u4E2D\u5730\u5F62\u7EA0\u7ED3\u3001\u6CE5\u6CDE\u96BE\u884C\uFF0C\u65E0\u8BBA\u8FFD\u527F\u76D7\u532A\u8FD8\u662F\u884C\u519B\u90FD\u5341\u5206\u8270\u96BE\u3002"},houses:["wylde","mertyns","morrigen"],refs:["acok","asos","adwd","twoiaf"],confidence:"high",spoiler:{en:"Stannis names Davos Seaworth Lord of the Rainwood, granting him lands on Cape Wrath (A Storm of Swords).",zh:"\u53F2\u5766\u5C3C\u65AF\u518C\u5C01\u6234\u4F5B\u65AF\xB7\u5E2D\u6E25\u65AF\u4E3A\u201C\u96E8\u6797\u4F2F\u7235\u201D\uFF0C\u8D50\u4ED6\u6012\u89D2\u4E0A\u7684\u9886\u5730\uFF08\u300A\u51B0\u96E8\u7684\u98CE\u66B4\u300B\uFF09\u3002"}},{id:"cape-wrath",kind:"landmark",region:"stormlands",at:[608,1100],rank:3,names:{en:"Cape Wrath",zh:"\u6012\u89D2"},summary:{en:"The great eastern peninsula of the stormlands, thrusting into the Narrow Sea between Shipbreaker Bay and the Sea of Dorne. Most of it lies under the Rainwood; Griffin's Roost, Rain House and Mistwood stand on or near it, and the isle of Tarth lies just off its eastern shore.",zh:"\u98CE\u66B4\u5730\u5411\u4E1C\u4F38\u5165\u72ED\u6D77\u7684\u5927\u534A\u5C9B\uFF0C\u5317\u4E34\u7834\u8239\u6E7E\uFF0C\u5357\u4E34\u591A\u6069\u6D77\u3002\u534A\u5C9B\u5927\u90E8\u4E3A\u96E8\u6797\u6240\u8986\u76D6\uFF0C\u72EE\u9E6B\u6816\u606F\u5730\u3001\u96E8\u5C4B\u4E0E\u96FE\u6797\u5821\u90FD\u5750\u843D\u4E8E\u5176\u4E0A\u6216\u9644\u8FD1\uFF0C\u5854\u65AF\u5C9B\u5C31\u5728\u5B83\u4E1C\u5CB8\u4E4B\u5916\u3002"},houses:[],refs:["acok","adwd","maps","twoiaf"],confidence:"high",spoiler:{en:"In A Dance with Dragons the Golden Company lands on Cape Wrath and quickly seizes several of its castles in the name of a young claimant presented as Aegon Targaryen.",zh:"\u5728\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u9EC4\u91D1\u56E2\u767B\u9646\u6012\u89D2\uFF0C\u4EE5\u4E00\u4F4D\u81EA\u79F0\u4F0A\u803F\xB7\u5766\u683C\u5229\u5B89\u7684\u5C11\u5E74\u7684\u540D\u4E49\u8FC5\u901F\u593A\u53D6\u4E86\u5F53\u5730\u6570\u5EA7\u57CE\u5821\u3002"}},{id:"shipbreaker-bay",kind:"bay",region:"stormlands",at:[580,1016],rank:4,names:{en:"Shipbreaker Bay",zh:"\u7834\u8239\u6E7E"},summary:{en:"The storm-wracked bay between Massey's Hook and Cape Wrath, with Storm's End on its western shore; its name is earned by the gales that sweep in from the Narrow Sea. Lord Steffon Baratheon and his wife Cassana drowned here when their ship broke apart within sight of the castle, watched by their sons Robert and Stannis.",zh:"\u4F4D\u4E8E\u6885\u897F\u94A9\u4E0E\u6012\u89D2\u4E4B\u95F4\u3001\u98CE\u66B4\u8086\u8650\u7684\u6D77\u6E7E\uFF0C\u98CE\u606F\u5821\u5750\u843D\u5728\u5176\u897F\u5CB8\uFF1B\u72ED\u6D77\u5439\u6765\u7684\u72C2\u98CE\u8BA9\u5B83\u540D\u526F\u5176\u5B9E\u3002\u53F2\u8482\u82AC\xB7\u62DC\u62C9\u5E2D\u6069\u516C\u7235\u4E0E\u59BB\u5B50\u5361\u73CA\u5A1C\u7684\u5EA7\u8239\u5C31\u5728\u57CE\u5821\u89C6\u91CE\u4E4B\u5185\u7684\u6D77\u9762\u4E0A\u89E3\u4F53\u6C89\u6CA1\uFF0C\u4ED6\u4EEC\u7684\u513F\u5B50\u52B3\u52C3\u4E0E\u53F2\u5766\u5C3C\u65AF\u4EB2\u773C\u76EE\u7779\u4E86\u8FD9\u4E00\u5E55\u3002"},houses:[],refs:["agot","acok","twoiaf"],confidence:"high"},{id:"sea-of-dorne",kind:"bay",region:"stormlands",at:[566,1162],rank:3,names:{en:"Sea of Dorne",zh:"\u591A\u6069\u6D77"},summary:{en:"The inland sea between the stormlands' southern coast and northern Dorne, opening east onto the Stepstones and the Narrow Sea. Stonehelm and Weeping Town stand on its northern shore, Dornish ports on the southern.",zh:"\u4ECB\u4E8E\u98CE\u66B4\u5730\u5357\u5CB8\u4E0E\u591A\u6069\u5317\u90E8\u4E4B\u95F4\u7684\u5185\u6D77\uFF0C\u5411\u4E1C\u901A\u5F80\u77F3\u9636\u5217\u5C9B\u4E0E\u72ED\u6D77\u3002\u77F3\u76D4\u57CE\u4E0E\u54ED\u6CE3\u9547\u4F4D\u4E8E\u5317\u5CB8\uFF0C\u591A\u6069\u7684\u6E2F\u53E3\u5219\u6563\u5E03\u4E8E\u5357\u5CB8\u3002"},houses:[],refs:["maps","twoiaf"],confidence:"high"},{id:"straits-of-tarth",kind:"bay",region:"stormlands",at:[650,1076],rank:2,names:{en:"Straits of Tarth",zh:"\u5854\u65AF\u6D77\u5CE1"},alt:["Tarth Straits"],summary:{en:"The narrow channel separating the isle of Tarth from the tip of Cape Wrath, a passage for ships rounding the stormlands between the Narrow Sea and the Sea of Dorne.",zh:"\u5206\u9694\u5854\u65AF\u5C9B\u4E0E\u6012\u89D2\u5C16\u7AEF\u7684\u72ED\u7A84\u6C34\u9053\uFF0C\u5F80\u6765\u4E8E\u72ED\u6D77\u4E0E\u591A\u6069\u6D77\u3001\u7ED5\u884C\u98CE\u66B4\u5730\u7684\u8239\u53EA\u591A\u7ECF\u6B64\u5904\u3002"},houses:[],refs:["maps","twoiaf"],confidence:"medium"},{id:"tarth",kind:"island",region:"stormlands",at:[657,1054],rank:3,names:{en:"Tarth",zh:"\u5854\u65AF\u5C9B"},alt:["Sapphire Isle","\u84DD\u5B9D\u77F3\u5C9B","\u5854\u65AF"],summary:{en:"A mountainous island off Cape Wrath, called the Sapphire Isle for the deep blue of the waters around it. It is ruled from Evenfall Hall by House Tarth, whose lord in the novels is Selwyn the Evenstar, father of Brienne.",zh:"\u6012\u89D2\u5916\u6D77\u7684\u4E00\u5EA7\u591A\u5C71\u5C9B\u5C7F\uFF0C\u56E0\u56DB\u5468\u6D77\u6C34\u6E5B\u84DD\u800C\u88AB\u79F0\u4E3A\u201C\u84DD\u5B9D\u77F3\u5C9B\u201D\u3002\u5854\u65AF\u5BB6\u65CF\u4ECE\u66AE\u4E34\u5385\u7EDF\u6CBB\u5168\u5C9B\uFF0C\u5C0F\u8BF4\u4E2D\u7684\u5C9B\u4E3B\u662F\u201C\u66AE\u661F\u201D\u8D5B\u5C14\u6E29\uFF0C\u5373\u5E03\u857E\u59AE\u7684\u7236\u4EB2\u3002"},houses:["tarth"],refs:["acok","affc","twoiaf"],confidence:"high"},{id:"estermont",kind:"island",region:"stormlands",at:[646,1126],rank:2,names:{en:"Estermont",zh:"\u4F0A\u65AF\u8499\u5C9B"},summary:{en:"An island off the southern tip of Cape Wrath, held by House Estermont from Greenstone. Through Lady Cassana Estermont, the mother of Robert, Stannis and Renly, the island's lords are close kin of the Baratheon kings.",zh:"\u6012\u89D2\u5357\u7AEF\u5916\u6D77\u7684\u4E00\u5EA7\u5C9B\u5C7F\uFF0C\u4F0A\u65AF\u8499\u5BB6\u65CF\u5728\u7EFF\u77F3\u5821\u7EDF\u6CBB\u6B64\u5C9B\u3002\u52B3\u52C3\u3001\u53F2\u5766\u5C3C\u65AF\u4E0E\u84DD\u793C\u7684\u6BCD\u4EB2\u5361\u73CA\u5A1C\u592B\u4EBA\u51FA\u8EAB\u4F0A\u65AF\u8499\u5BB6\u65CF\uFF0C\u56E0\u6B64\u5C9B\u4E0A\u7684\u9886\u4E3B\u4E0E\u62DC\u62C9\u5E2D\u6069\u8BF8\u738B\u662F\u8FD1\u4EB2\u3002"},houses:["estermont"],refs:["acok","affc","twoiaf"],confidence:"high"},{id:"dornish-marches",kind:"mountain",region:"stormlands",at:[440,1124],rank:3,names:{en:"The Dornish Marches",zh:"\u591A\u6069\u8FB9\u7586\u5730"},alt:["Marches","the Marches","\u8FB9\u7586\u5730"],summary:{en:"The hilly borderland along the northern foothills of the Red Mountains, where the stormlands and the Reach face Dorne. Its marcher lords \u2014 Caron, Dondarrion, Swann, Selmy and others \u2014 kept watch on the mountain passes through centuries of border war.",zh:"\u8D64\u7EA2\u5C71\u8109\u5317\u9E93\u7684\u4E18\u9675\u8FB9\u5730\uFF0C\u98CE\u66B4\u5730\u4E0E\u6CB3\u6E7E\u5730\u5728\u6B64\u4E0E\u591A\u6069\u5BF9\u5CD9\u3002\u5361\u4F26\u3001\u5510\u5FB7\u5229\u6069\u3001\u53F2\u6587\u3001\u8D5B\u5C14\u5F25\u7B49\u8FB9\u7586\u8BF8\u4FAF\u4E16\u4EE3\u627C\u5B88\u5C71\u53E3\uFF0C\u7ECF\u5386\u4E86\u6570\u767E\u5E74\u7684\u8FB9\u5883\u6218\u4E89\u3002"},houses:["caron","dondarrion","swann","selmy"],refs:["agot","acok","twoiaf"],confidence:"high"},{id:"bronzegate",kind:"castle",region:"stormlands",at:[494,1004],rank:2,names:{en:"Bronzegate",zh:"\u94DC\u95E8\u57CE"},summary:{en:"Seat of House Buckler, standing by the kingsroad on the way from King's Landing to Storm's End, near the southern edge of the Kingswood. The castle takes its name from its gates of bronze; the Bucklers are old bannermen of Storm's End.",zh:"\u5DF4\u514B\u52D2\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u4ECE\u541B\u4E34\u524D\u5F80\u98CE\u606F\u5821\u7684\u56FD\u738B\u5927\u9053\u65C1\uFF0C\u4E34\u8FD1\u5FA1\u6797\u5357\u7F18\u3002\u57CE\u5821\u56E0\u5176\u9752\u94DC\u5927\u95E8\u800C\u5F97\u540D\uFF1B\u5DF4\u514B\u52D2\u5BB6\u65CF\u662F\u98CE\u606F\u5821\u7684\u8001\u5C01\u81E3\u3002"},houses:["buckler"],refs:["acok","twoiaf"],confidence:"medium"},{id:"felwood",kind:"castle",region:"stormlands",at:[486,1040],rank:2,names:{en:"Felwood",zh:"\u8D39\u5C14\u6797\u5821"},summary:{en:"Seat of House Fell in the northern stormlands. Lord Fell was one of the loyalist lords Robert Baratheon defeated in the three battles he fought in a single day at Summerhall early in his rebellion.",zh:"\u8D39\u5C14\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u98CE\u66B4\u5730\u5317\u90E8\u3002\u52B3\u52C3\u8D77\u5175\u4E4B\u521D\u66FE\u5728\u76DB\u590F\u5385\u4E00\u65E5\u4E4B\u5185\u8FDE\u6253\u4E09\u4ED7\uFF0C\u8D39\u5C14\u516C\u7235\u4FBF\u662F\u88AB\u4ED6\u51FB\u8D25\u7684\u6548\u5FE0\u738B\u5BA4\u7684\u9886\u4E3B\u4E4B\u4E00\u3002"},houses:["fell"],refs:["twoiaf"],confidence:"low"},{id:"haystack-hall",kind:"castle",region:"stormlands",at:[562,1046],rank:2,names:{en:"Haystack Hall",zh:"\u8349\u579B\u5385"},summary:{en:"Seat of House Errol, near the shore of Shipbreaker Bay between Storm's End and Cape Wrath. The Errols are a minor house sworn to Storm's End.",zh:"\u827E\u7F57\u5C14\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u7834\u8239\u6E7E\u6CBF\u5CB8\uFF0C\u4ECB\u4E8E\u98CE\u606F\u5821\u4E0E\u6012\u89D2\u4E4B\u95F4\u3002\u827E\u7F57\u5C14\u5BB6\u65CF\u662F\u6548\u5FE0\u98CE\u606F\u5821\u7684\u5C0F\u5BB6\u65CF\u3002"},houses:["errol"],refs:["adwd","twoiaf"],confidence:"low",spoiler:{en:"The Golden Company takes Haystack Hall during its campaign in the stormlands (A Dance with Dragons).",zh:"\u9EC4\u91D1\u56E2\u5728\u98CE\u66B4\u5730\u4F5C\u6218\u671F\u95F4\u653B\u5360\u4E86\u8349\u579B\u5385\uFF08\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\uFF09\u3002"}},{id:"parchments",kind:"castle",region:"stormlands",at:[546,1062],rank:1,names:{en:"Parchments",zh:"\u7F8A\u76AE\u7EB8\u57CE"},summary:{en:"Seat of House Penrose, whose arms show crossed quills. Ser Cortnay Penrose of this house was castellan of Storm's End for Stannis in 299 AC. The castle's position is not described; it is placed here only within the northern stormlands.",zh:"\u76D8\u7F57\u65AF\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5176\u7EB9\u7AE0\u4E3A\u4EA4\u53C9\u7684\u7FBD\u6BDB\u7B14\u3002299\u5E74\u4E3A\u53F2\u5766\u5C3C\u65AF\u9547\u5B88\u98CE\u606F\u5821\u7684\u4EE3\u7406\u57CE\u4E3B\u79D1\u5854\u5948\xB7\u76D8\u7F57\u65AF\u7235\u58EB\u5373\u51FA\u8EAB\u6B64\u5BB6\u3002\u4E66\u4E2D\u672A\u63CF\u8FF0\u57CE\u5821\u4F4D\u7F6E\uFF0C\u6B64\u5904\u4EC5\u5927\u81F4\u6807\u5728\u98CE\u66B4\u5730\u5317\u90E8\u3002"},houses:["penrose"],refs:["acok","twoiaf"],confidence:"low"},{id:"gallowsgrey",kind:"castle",region:"stormlands",at:[514,1074],rank:1,names:{en:"Gallowsgrey",zh:"\u7070\u7EDE\u67B6\u5821"},summary:{en:"Seat of House Trant, a minor stormland house best known for Ser Meryn Trant of King Joffrey's Kingsguard. Its exact location is not given; the marker is approximate.",zh:"\u7279\u6069\u7279\u5BB6\u65CF\u7684\u5C45\u57CE\u3002\u8FD9\u4E00\u98CE\u66B4\u5730\u5C0F\u5BB6\u65CF\u6700\u51FA\u540D\u7684\u6210\u5458\u662F\u4E54\u4F5B\u91CC\u56FD\u738B\u7684\u5FA1\u6797\u94C1\u536B\u9A6C\u6797\xB7\u7279\u6069\u7279\u7235\u58EB\u3002\u57CE\u5821\u786E\u5207\u4F4D\u7F6E\u4E0D\u8BE6\uFF0C\u6B64\u5904\u6807\u6CE8\u4EC5\u4E3A\u5927\u81F4\u3002"},houses:["trant"],refs:["agot","twoiaf"],confidence:"low"},{id:"the-last-storm",kind:"battle",region:"stormlands",at:[512,1044],rank:2,names:{en:"The Last Storm",zh:"\u6700\u540E\u7684\u98CE\u66B4"},alt:["Battle of the Last Storm"],summary:{en:"The battle of Aegon's Conquest in which Orys Baratheon defeated Argilac the Arrogant, last of the Storm Kings, and slew him. Orys then wed Argilac's daughter Argella and took his arms and words, founding House Baratheon at Storm's End. The exact field is not fixed; it is marked near the castle.",zh:"\u4F0A\u803F\u5F81\u670D\u6218\u4E89\u4E2D\u7684\u4E00\u573A\u6218\u5F79\uFF1A\u5965\u91CC\u65AF\xB7\u62DC\u62C9\u5E2D\u6069\u51FB\u8D25\u5E76\u65A9\u6740\u4E86\u672B\u4EE3\u98CE\u66B4\u4E4B\u738B\u201C\u50B2\u6162\u7684\u201D\u963F\u57FA\u62C9\u514B\u3002\u968F\u540E\u5965\u91CC\u65AF\u5A36\u4E86\u963F\u57FA\u62C9\u514B\u4E4B\u5973\u963F\u6377\u62C9\uFF0C\u627F\u88AD\u5176\u7EB9\u7AE0\u4E0E\u65CF\u8BED\uFF0C\u5728\u98CE\u606F\u5821\u5F00\u521B\u62DC\u62C9\u5E2D\u6069\u5BB6\u65CF\u3002\u6218\u573A\u786E\u5207\u4F4D\u7F6E\u4E0D\u8BE6\uFF0C\u6B64\u5904\u6807\u5728\u98CE\u606F\u5821\u9644\u8FD1\u3002"},houses:["durrandon","baratheon"],refs:["agot","twoiaf"],confidence:"medium"},{id:"fawnton",kind:"castle",region:"stormlands",at:[468,1056],rank:1,names:{en:"Fawnton",zh:"\u5C0F\u9E7F\u57CE"},summary:{en:"Seat of House Cafferen in the western stormlands. Lord Cafferen marched for King Aerys early in Robert's Rebellion and was beaten by Robert at Summerhall.",zh:"\u5361\u592B\u4F26\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u98CE\u66B4\u5730\u897F\u90E8\u3002\u52B3\u52C3\u53DB\u4E71\u4E4B\u521D\uFF0C\u5361\u592B\u4F26\u516C\u7235\u4E3E\u5175\u652F\u6301\u4F0A\u91CC\u65AF\u56FD\u738B\uFF0C\u7ED3\u679C\u5728\u76DB\u590F\u5385\u8D25\u4E8E\u52B3\u52C3\u4E4B\u624B\u3002"},houses:["cafferen"],refs:["twoiaf"],confidence:"low"},{id:"grandview",kind:"castle",region:"stormlands",at:[458,1082],rank:1,names:{en:"Grandview",zh:"\u8FDC\u666F\u5821"},summary:{en:"Seat of House Grandison in the western stormlands. Lord Grandison was among the loyalist lords who gathered at Summerhall against Robert in 282 AC and were defeated there.",zh:"\u845B\u5170\u72C4\u68EE\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u98CE\u66B4\u5730\u897F\u90E8\u3002282\u5E74\uFF0C\u845B\u5170\u72C4\u68EE\u516C\u7235\u4E0E\u5176\u4ED6\u6548\u5FE0\u738B\u5BA4\u7684\u9886\u4E3B\u805A\u96C6\u76DB\u590F\u5385\u8BA8\u4F10\u52B3\u52C3\uFF0C\u5374\u5728\u90A3\u91CC\u6218\u8D25\u3002"},houses:["grandison"],refs:["twoiaf"],confidence:"low"},{id:"poddingfield",kind:"castle",region:"stormlands",at:[500,1092],rank:1,names:{en:"Poddingfield",zh:"\u8C46\u7530\u5821"},summary:{en:"Seat of House Peasebury, a minor house of the stormlands sworn to Storm's End. Little is told of the castle itself, and its position is a guess.",zh:"\u76AE\u65AF\u4F2F\u91CC\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u8FD9\u662F\u6548\u5FE0\u98CE\u606F\u5821\u7684\u4E00\u4E2A\u98CE\u66B4\u5730\u5C0F\u5BB6\u65CF\u3002\u4E66\u4E2D\u5BF9\u57CE\u5821\u672C\u8EAB\u5C11\u6709\u8BB0\u8FF0\uFF0C\u6B64\u5904\u4F4D\u7F6E\u7EAF\u5C5E\u63A8\u6D4B\u3002"},houses:["peasebury"],refs:["twoiaf"],confidence:"low"},{id:"amberly",kind:"castle",region:"stormlands",at:[530,1100],rank:1,names:{en:"Amberly",zh:"\u5B89\u67CF\u5229"},summary:{en:"Seat of House Rogers, a minor stormland house. It is named in the companion histories, which give no detail of its setting; the marker is approximate.",zh:"\u7F57\u6770\u65AF\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u8FD9\u662F\u98CE\u66B4\u5730\u7684\u4E00\u4E2A\u5C0F\u5BB6\u65CF\u3002\u6B64\u5730\u4EC5\u89C1\u4E8E\u5B98\u65B9\u7F16\u5E74\u53F2\uFF0C\u672A\u8FF0\u5176\u73AF\u5883\uFF0C\u6B64\u5904\u6807\u6CE8\u4EC5\u4E3A\u5927\u81F4\u3002"},houses:["rogers"],refs:["twoiaf"],confidence:"low"},{id:"broad-arch",kind:"castle",region:"stormlands",at:[520,1120],rank:1,names:{en:"Broad Arch",zh:"\u5BBD\u62F1\u5821"},summary:{en:"Seat of House Staedmon in the stormlands. The histories recall a Lord Staedmon nicknamed Pennylover for his thrift. Position approximate.",zh:"\u53F2\u6234\u8499\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u98CE\u66B4\u5730\u3002\u53F2\u4E66\u4E2D\u6709\u4E00\u4F4D\u4EE5\u541D\u556C\u51FA\u540D\u3001\u7EF0\u53F7\u201C\u7231\u8D22\u8005\u201D\u7684\u53F2\u6234\u8499\u4F2F\u7235\u3002\u6B64\u5904\u4F4D\u7F6E\u4EC5\u4E3A\u5927\u81F4\u3002"},houses:["staedmon"],refs:["twoiaf"],confidence:"low"},{id:"griffins-roost",kind:"castle",region:"stormlands",at:[592,1056],rank:3,names:{en:"Griffin's Roost",zh:"\u72EE\u9E6B\u6816\u606F\u5730"},summary:{en:"Seat of House Connington, perched on a crag above Shipbreaker Bay on the northern side of Cape Wrath. Its lord Jon Connington served Aerys II as Hand, failed to catch Robert at Stoney Sept in the Battle of the Bells, and was exiled; the house lost much of its land and standing.",zh:"\u514B\u6797\u987F\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u9AD8\u8E1E\u6012\u89D2\u5317\u4FA7\u3001\u4FEF\u77B0\u7834\u8239\u6E7E\u7684\u4E00\u5EA7\u5CA9\u5CF0\u4E4B\u4E0A\u3002\u5176\u9886\u4E3B\u743C\u6069\xB7\u514B\u6797\u987F\u66FE\u4EFB\u4F0A\u91CC\u65AF\u4E8C\u4E16\u7684\u9996\u76F8\uFF0C\u5728\u77F3\u5802\u9547\u201C\u949F\u697C\u4E4B\u5F79\u201D\u4E2D\u672A\u80FD\u64D2\u83B7\u52B3\u52C3\uFF0C\u56E0\u800C\u906D\u5230\u6D41\u653E\uFF1B\u5BB6\u65CF\u4E5F\u968F\u4E4B\u5931\u53BB\u5927\u7247\u9886\u5730\u4E0E\u5730\u4F4D\u3002"},houses:["connington"],refs:["asos","adwd","twoiaf"],confidence:"medium",spoiler:{en:"Jon Connington, long believed dead, returns with the Golden Company and retakes Griffin's Roost by surprise (A Dance with Dragons).",zh:"\u4EBA\u4EEC\u957F\u4E45\u4EE5\u4E3A\u5DF2\u6B7B\u7684\u743C\u6069\xB7\u514B\u6797\u987F\u968F\u9EC4\u91D1\u56E2\u5F52\u6765\uFF0C\u4EE5\u5947\u88AD\u593A\u56DE\u72EE\u9E6B\u6816\u606F\u5730\uFF08\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\uFF09\u3002"}},{id:"rain-house",kind:"castle",region:"stormlands",at:[624,1088],rank:2,names:{en:"Rain House",zh:"\u96E8\u5C4B"},summary:{en:"Seat of House Wylde near the eastern end of Cape Wrath, facing the Straits of Tarth. Lord Casper Wylde is one of the stormlords of the War of the Five Kings.",zh:"\u5A01\u5C14\u5FB7\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u6012\u89D2\u4E1C\u7AEF\u9644\u8FD1\uFF0C\u9762\u5BF9\u5854\u65AF\u6D77\u5CE1\u3002\u5361\u65AF\u73C0\xB7\u5A01\u5C14\u5FB7\u4F2F\u7235\u662F\u4E94\u738B\u4E4B\u6218\u4E2D\u7684\u98CE\u66B4\u5730\u8BF8\u4FAF\u4E4B\u4E00\u3002"},houses:["wylde"],refs:["acok","adwd","twoiaf"],confidence:"medium"},{id:"mistwood",kind:"castle",region:"stormlands",at:[582,1088],rank:2,names:{en:"Mistwood",zh:"\u96FE\u6797\u5821"},summary:{en:"Seat of House Mertyns, standing in the damp depths of the Rainwood on Cape Wrath.",zh:"\u6885\u5C14\u5EF7\u65AF\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u5728\u6012\u89D2\u96E8\u6797\u6F6E\u6E7F\u7684\u6DF1\u5904\u3002"},houses:["mertyns"],refs:["adwd","twoiaf"],confidence:"low",spoiler:{en:"Mistwood falls to the Golden Company in A Dance with Dragons.",zh:"\u5728\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u96FE\u6797\u5821\u88AB\u9EC4\u91D1\u56E2\u653B\u9677\u3002"}},{id:"crows-nest",kind:"castle",region:"stormlands",at:[602,1118],rank:2,names:{en:"Crow's Nest",zh:"\u9E26\u5DE2\u5821"},summary:{en:"Seat of House Morrigen on Cape Wrath, whose arms show a crow in flight. Ser Guyard Morrigen of this house was one of Renly's Rainbow Guard.",zh:"\u83AB\u91CC\u6839\u5BB6\u65CF\u5728\u6012\u89D2\u7684\u5C45\u57CE\uFF0C\u5176\u7EB9\u7AE0\u662F\u4E00\u53EA\u5C55\u7FC5\u7684\u4E4C\u9E26\u3002\u8BE5\u5BB6\u65CF\u7684\u76D6\u4E9A\u5FB7\xB7\u83AB\u91CC\u6839\u7235\u58EB\u662F\u84DD\u793C\u7684\u5F69\u8679\u62A4\u536B\u4E4B\u4E00\u3002"},houses:["morrigen"],refs:["acok","adwd","twoiaf"],confidence:"low",spoiler:{en:"Crow's Nest is taken by the Golden Company in A Dance with Dragons.",zh:"\u5728\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u9E26\u5DE2\u5821\u88AB\u9EC4\u91D1\u56E2\u593A\u53D6\u3002"}},{id:"evenfall-hall",kind:"castle",region:"stormlands",at:[668,1051],rank:3,names:{en:"Evenfall Hall",zh:"\u66AE\u4E34\u5385"},alt:["Evenfall"],summary:{en:"Seat of House Tarth on the Sapphire Isle, home of Lord Selwyn the Evenstar and his daughter Brienne. Brienne remembers it as a hall above the sea, where she grew up tall, awkward and set on the sword.",zh:"\u5854\u65AF\u5BB6\u65CF\u5728\u84DD\u5B9D\u77F3\u5C9B\u4E0A\u7684\u5C45\u57CE\uFF0C\u201C\u66AE\u661F\u201D\u8D5B\u5C14\u6E29\u4F2F\u7235\u4E0E\u5973\u513F\u5E03\u857E\u59AE\u7684\u5BB6\u3002\u5728\u5E03\u857E\u59AE\u7684\u56DE\u5FC6\u91CC\uFF0C\u90A3\u662F\u4E00\u5EA7\u4E34\u6D77\u7684\u5385\u5802\uFF0C\u5979\u5728\u90A3\u91CC\u957F\u6210\u4E86\u4E00\u4E2A\u9AD8\u5927\u7B28\u62D9\u3001\u4E00\u5FC3\u4E60\u5251\u7684\u59D1\u5A18\u3002"},houses:["tarth"],refs:["acok","affc","twoiaf"],confidence:"high"},{id:"morne",kind:"ruin",region:"stormlands",at:[646,1061],rank:1,names:{en:"Morne",zh:"\u83AB\u6069"},summary:{en:"A ruined stronghold on Tarth, mentioned in passing as one of the island's ancient places. Nothing certain is told of who built it; its position on the island is a guess.",zh:"\u5854\u65AF\u5C9B\u4E0A\u7684\u4E00\u5904\u8981\u585E\u5E9F\u589F\uFF0C\u4E66\u4E2D\u4EC5\u987A\u5E26\u63D0\u53CA\uFF0C\u662F\u5C9B\u4E0A\u7684\u53E4\u8FF9\u4E4B\u4E00\u3002\u4F55\u4EBA\u6240\u5EFA\u5E76\u65E0\u786E\u5207\u8BB0\u8F7D\uFF0C\u5176\u5728\u5C9B\u4E0A\u7684\u4F4D\u7F6E\u4EA6\u5C5E\u63A8\u6D4B\u3002"},houses:[],refs:["affc"],confidence:"low"},{id:"greenstone",kind:"castle",region:"stormlands",at:[650,1123],rank:2,names:{en:"Greenstone",zh:"\u7EFF\u77F3\u5821"},summary:{en:"Seat of House Estermont on the island of Estermont. Lord Eldon Estermont, uncle of King Robert, and his son and grandson appear in the novels.",zh:"\u4F0A\u65AF\u8499\u5BB6\u65CF\u5728\u4F0A\u65AF\u8499\u5C9B\u4E0A\u7684\u5C45\u57CE\u3002\u5C0F\u8BF4\u4E2D\u51FA\u73B0\u8FC7\u52B3\u52C3\u56FD\u738B\u7684\u8205\u7236\u827E\u5C14\u767B\xB7\u4F0A\u65AF\u8499\u4F2F\u7235\u53CA\u5176\u5B50\u5B59\u3002"},houses:["estermont"],refs:["acok","affc","adwd","twoiaf"],confidence:"medium"},{id:"summerhall",kind:"ruin",region:"stormlands",at:[480,1108],rank:3,names:{en:"Summerhall",zh:"\u76DB\u590F\u5385"},summary:{en:"A Targaryen summer palace in the southern stormlands, destroyed by fire in 259 AC at a feast where King Aegon V, his son Prince Duncan and Ser Duncan the Tall died; Prince Rhaegar was born amid the disaster and later haunted its ruins with his harp. Early in his rebellion Robert Baratheon won three battles there in a single day.",zh:"\u5766\u683C\u5229\u5B89\u5BB6\u65CF\u4F4D\u4E8E\u98CE\u66B4\u5730\u5357\u90E8\u7684\u590F\u5BAB\u3002259\u5E74\u7684\u4E00\u573A\u5BB4\u4F1A\u4E0A\u5927\u706B\u711A\u6BC1\u4E86\u5BAB\u6BBF\uFF0C\u4F0A\u803F\u4E94\u4E16\u56FD\u738B\u3001\u5176\u5B50\u9093\u80AF\u738B\u5B50\u4E0E\u201C\u9AD8\u4E2A\u5B50\u201D\u9093\u80AF\u7235\u58EB\u7686\u846C\u8EAB\u706B\u6D77\uFF1B\u96F7\u52A0\u738B\u5B50\u6070\u5728\u8FD9\u573A\u707E\u96BE\u4E2D\u964D\u751F\uFF0C\u65E5\u540E\u5E38\u643A\u7AD6\u7434\u6D41\u8FDE\u4E8E\u5E9F\u589F\u4E4B\u95F4\u3002\u52B3\u52C3\u8D77\u5175\u4E4B\u521D\uFF0C\u66FE\u5728\u6B64\u5730\u4E00\u65E5\u4E4B\u5185\u8FDE\u80DC\u4E09\u4ED7\u3002"},houses:[],refs:["agot","asos","twoiaf"],confidence:"high"},{id:"harvest-hall",kind:"castle",region:"stormlands",at:[450,1104],rank:2,names:{en:"Harvest Hall",zh:"\u4E30\u6536\u5385"},summary:{en:"Seat of House Selmy, a modest knightly house of the Dornish Marches whose arms bear sheaves of wheat. Its most famous son is Ser Barristan Selmy, called the Bold, Lord Commander of the Kingsguard under Robert.",zh:"\u8D5B\u5C14\u5F25\u5BB6\u65CF\u7684\u5C45\u57CE\u3002\u8FD9\u662F\u591A\u6069\u8FB9\u7586\u5730\u4E0A\u4E00\u4E2A\u4E0D\u7B97\u663E\u8D6B\u7684\u9A91\u58EB\u5BB6\u65CF\uFF0C\u7EB9\u7AE0\u4E0A\u7ED8\u6709\u9EA6\u675F\u3002\u5BB6\u65CF\u6700\u8457\u540D\u7684\u6210\u5458\u662F\u201C\u65E0\u754F\u7684\u201D\u5DF4\u5229\u65AF\u5766\xB7\u8D5B\u5C14\u5F25\u7235\u58EB\uFF0C\u52B3\u52C3\u5728\u4F4D\u65F6\u4EFB\u5FA1\u6797\u94C1\u536B\u961F\u957F\u3002"},houses:["selmy"],refs:["agot","twoiaf"],confidence:"low"},{id:"blackhaven",kind:"castle",region:"stormlands",at:[420,1132],rank:2,names:{en:"Blackhaven",zh:"\u9ED1\u6E2F\u57CE"},summary:{en:"Seat of House Dondarrion in the Dornish Marches, beneath the Red Mountains. Its young lord Beric Dondarrion was sent by Eddard Stark to bring Gregor Clegane to justice in the riverlands.",zh:"\u5510\u5FB7\u5229\u6069\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u8D64\u7EA2\u5C71\u8109\u811A\u4E0B\u7684\u591A\u6069\u8FB9\u7586\u5730\u3002\u5E74\u8F7B\u7684\u9886\u4E3B\u8D1D\u91CC\xB7\u5510\u5FB7\u5229\u6069\u5949\u827E\u5FB7\xB7\u53F2\u5854\u514B\u4E4B\u547D\u524D\u5F80\u6CB3\u95F4\u5730\uFF0C\u6349\u62FF\u683C\u96F7\u679C\xB7\u514B\u91CC\u5188\u5F52\u6848\u3002"},houses:["dondarrion"],refs:["agot","asos","twoiaf"],confidence:"medium"},{id:"nightsong",kind:"castle",region:"stormlands",at:[374,1146],rank:2,names:{en:"Nightsong",zh:"\u591C\u6B4C\u57CE"},summary:{en:"Seat of House Caron, marcher lords of the westernmost stormlands who guard the approaches from the Dornish mountains; their arms show nightingales. Lord Bryce Caron served in Renly's Rainbow Guard.",zh:"\u5361\u4F26\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u8FD9\u652F\u8FB9\u7586\u8BF8\u4FAF\u9547\u5B88\u98CE\u66B4\u5730\u6700\u897F\u7AEF\uFF0C\u627C\u5B88\u6765\u81EA\u591A\u6069\u7FA4\u5C71\u7684\u901A\u9053\uFF1B\u5176\u7EB9\u7AE0\u7ED8\u6709\u591C\u83BA\u3002\u5E03\u83B1\u65AF\xB7\u5361\u4F26\u4F2F\u7235\u66FE\u662F\u84DD\u793C\u7684\u5F69\u8679\u62A4\u536B\u3002"},houses:["caron"],refs:["acok","twoiaf"],confidence:"medium"},{id:"stonehelm",kind:"castle",region:"stormlands",at:[494,1144],rank:2,names:{en:"Stonehelm",zh:"\u77F3\u76D4\u57CE"},summary:{en:"Seat of House Swann near the Sea of Dorne, guarding the northern end of the Boneway, the mountain road into Dorne. The Swanns' black and white swans are borne by Lord Gulian and his sons Balon and Donnel.",zh:"\u53F2\u6587\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4E34\u8FD1\u591A\u6069\u6D77\uFF0C\u627C\u5B88\u901A\u5F80\u591A\u6069\u7684\u5C71\u8DEF\u201C\u9AB8\u9AA8\u8DEF\u201D\u5317\u7AEF\u3002\u53E4\u5229\u5B89\u4F2F\u7235\u53CA\u5176\u5B50\u62DC\u4F26\u3001\u5510\u7EB3\u5C14\u90FD\u4F69\u6234\u53F2\u6587\u5BB6\u65CF\u9ED1\u767D\u53CC\u5929\u9E45\u7684\u7EB9\u7AE0\u3002"},houses:["swann"],refs:["acok","asos","twoiaf"],confidence:"medium"},{id:"weeping-town",kind:"town",region:"stormlands",at:[540,1124],rank:1,names:{en:"Weeping Town",zh:"\u54ED\u6CE3\u9547"},summary:{en:"A small port on the southern coast of the stormlands, looking across the Sea of Dorne. It is named in the histories but hardly described, and its position on the coast is approximate.",zh:"\u98CE\u66B4\u5730\u5357\u90E8\u6D77\u5CB8\u7684\u4E00\u5EA7\u5C0F\u6E2F\uFF0C\u9694\u7740\u591A\u6069\u6D77\u4E0E\u5BF9\u5CB8\u76F8\u671B\u3002\u53F2\u4E66\u867D\u63D0\u53CA\u5176\u540D\uFF0C\u5374\u51E0\u4E4E\u672A\u52A0\u63CF\u8FF0\uFF0C\u5176\u5728\u6D77\u5CB8\u4E0A\u7684\u4F4D\u7F6E\u4EA6\u5C5E\u5927\u81F4\u3002"},houses:[],refs:["twoiaf"],confidence:"low"}]};export{e as default};
